test "wide: sorting and matching at L=60" {
    try std.testing.expect(Ecs.archetype_count == N_ARCH);
    try std.testing.expect(Ecs.component_count >= 80);
    const allocator = std.testing.allocator;
    defer Ecs.deinit(allocator);
    const handler = Ecs.SystemHandler{ .allocator = allocator };
    const all = handler.pages(&[_]type{Base0}, null).allPages();
    try std.testing.expect(all.len == N_ARCH);
    for (all[1..], 1..) |p, i| {
        try std.testing.expect(all[i - 1].arch_id < p.arch_id);
    }
    var expect_c0: usize = 0;
    for (0..Ecs.archetype_count) |a| {
        if (Ecs.hasComponent(@intCast(a), Ecs.componentId(C0))) {
            expect_c0 += 1;
        }
    }
    try std.testing.expect(handler.pages(&[_]type{C0}, null).allPages().len == expect_c0);
    try std.testing.expect(handler.pages(&[_]type{Base0}, null).nonEmptyPages().len == 0);
}

